import { createHash } from 'node:crypto'

import { describe, expect, it } from 'vitest'

import { crc24, dearmor } from './pgp-dearmor.ts'

/*
 * Every armored block in this file was produced by GnuPG 2.4.8 and pasted in
 * verbatim, checksum line included. That is the whole value of testing a
 * vendored envelope parser: armor written by the encoder that lives two
 * screens up would only prove the two halves of this module agree with each
 * other, and the details that break an armor reader — a `Comment:` header
 * before the body, a body wrapped at 64 characters, a final line carrying
 * padding — are exactly the ones a round trip never exercises.
 *
 * The CRC-24 values are checked the same way: `0xba1c7b` for `abc` is what
 * `printf abc | gpg --enarmor` prints on its `=` line, and `0x21cf02` for
 * `123456789` is the published check value of CRC-24/OpenPGP, so between
 * them the implementation is pinned to something other than itself.
 *
 * The bytes are compared against `node:crypto` and Node's own base64 decoder
 * where a 239-byte literal would be unreadable. Node is a reference here and
 * nowhere else: nothing in `src/tools/` can use it, since the page runs in a
 * browser.
 */

const utf8 = new TextEncoder()

/** `printf 'abc' | gpg --enarmor`. Three bytes, one body line, and the
 * `Comment:` header GnuPG adds — the smallest complete envelope there is. */
const ABC_BLOCK = `-----BEGIN PGP ARMORED FILE-----
Comment: Use "gpg --dearmor" for unpacking

YWJj
=uhx7
-----END PGP ARMORED FILE-----`

/** `gpg --enarmor` over 200 bytes generated by the rule below: five body
 * lines, so the parser has to concatenate before decoding rather than after,
 * and a last line that is shorter than the rest and padded. */
const WRAPPED_BLOCK = `-----BEGIN PGP ARMORED FILE-----
Comment: Use "gpg --dearmor" for unpacking

DRQbIikwNz5FTFNaYWhvdn2Ei5KZoKeutbzDytHY3+bt9PsCCRAXHiUsMzpBSE9W
XWRrcnmAh46VnKOqsbi/xs3U2+Lp8Pf+BQwTGiEoLzY9REtSWWBnbnV8g4qRmJ+m
rbS7wsnQ197l7PP6AQgPFh0kKzI5QEdOVVxjanF4f4aNlJuiqbC3vsXM09rh6O/2
/QQLEhkgJy41PENKUVhfZm10e4KJkJeepayzusHIz9bd5Ovy+QAHDhUcIyoxOD9G
TVRbYmlwd34=
=BcwQ
-----END PGP ARMORED FILE-----`

/** The 200 bytes `WRAPPED_BLOCK` was made from. Generated rather than
 * written out: two hundred hand-typed numbers prove nothing the rule does
 * not, and the rule is the one `md5.test.ts` already uses. */
const WRAPPED_BYTES = Uint8Array.from(
  { length: 200 },
  (_unused, index) => (index * 7 + 13) % 256,
)

/** A real `gpg --armor --export` of an ed25519 certification key, generated
 * for this test and never used for anything: no armor headers at all, which
 * is what a modern GnuPG emits, and a public-key packet followed by a User
 * ID and a self-signature. */
const KEY_BLOCK = `-----BEGIN PGP PUBLIC KEY BLOCK-----

mDMEaqI/oxYJKwYBBAHaRw8BAQdAmWkN2iNZ2aD4VmRFfOpP/5SJJzpAhFrpvIPG
ByakGti0JkRlYXJtb3IgVGVzdCA8ZGVhcm1vckBleGFtcGxlLmludmFsaWQ+iJAE
ExYKADgWIQQdkZg300K/AKomkguet+3Kja5cMAUCaqI/owIbAQULCQgHAgYVCgkI
CwIEFgIDAQIeAQIXgAAKCRCet+3Kja5cMLVYAP9+Ps1guiWGtphHMO9Y4kVskpzl
RpaKdjxlxu7cuYSPUwEA/U8/cIo0wageCs7Z/kNgBZzdKHIniv2DCcZCHEji5go=
=Xb+r
-----END PGP PUBLIC KEY BLOCK-----`

/** What `gpg --export | sha256sum` printed for the same key. */
const KEY_SHA256 =
  'a5dde78316cdfe09ce612f9281d6e6f5ecabf2779e4b551542f5309e47dc1918'

const sha256 = (bytes: Uint8Array): string =>
  createHash('sha256').update(bytes).digest('hex')

describe('crc24', () => {
  it('checksums the bytes of `abc` the way gpg --enarmor does', () => {
    expect(crc24(utf8.encode('abc'))).toBe(0xba1c7b)
  })

  it('matches the published CRC-24/OpenPGP check value', () => {
    // width=24 poly=0x864cfb init=0xb704ce refin=false refout=false
    // xorout=0x000000 check=0x21cf02, over the string '123456789'.
    expect(crc24(utf8.encode('123456789'))).toBe(0x21cf02)
  })

  it('returns the initial value for no bytes at all', () => {
    // The init constant is what makes leading zeroes count; an empty message
    // is the one input that reads it straight back out.
    expect(crc24(new Uint8Array(0))).toBe(0xb704ce)
  })

  it('agrees with the checksum gpg wrote over 239 bytes of real key', () => {
    const { data } = dearmor(KEY_BLOCK)
    expect(crc24(data)).toBe(0x5dbfab)
  })

  it('always returns 24 bits, never a negative number', () => {
    // The reduction step leaves bit 24 set before it is masked off, so a
    // missing mask would surface as a value above 0xffffff or, once the sign
    // bit is reached, below zero.
    for (let length = 0; length < 40; length += 1) {
      const bytes = Uint8Array.from({ length }, () => 0xff)
      const checksum = crc24(bytes)
      expect(checksum).toBeGreaterThanOrEqual(0)
      expect(checksum).toBeLessThanOrEqual(0xffffff)
    }
  })

  it('checksums a view into a larger buffer, not the whole buffer', () => {
    // A caller's `Uint8Array` may be a window onto something bigger, and
    // checksumming the backing buffer would be a silent wrong answer.
    const backing = Uint8Array.from([9, 9, 0x61, 0x62, 0x63, 9])
    expect(crc24(backing.subarray(2, 5))).toBe(0xba1c7b)
  })
})

describe('dearmor', () => {
  it('recovers the bytes of a single-line block', () => {
    const { data, crcOk } = dearmor(ABC_BLOCK)

    expect(crcOk).toBe(true)
    expect(Array.from(data)).toEqual([0x61, 0x62, 0x63])
  })

  it('concatenates wrapped body lines before decoding', () => {
    const { data, crcOk } = dearmor(WRAPPED_BLOCK)

    expect(crcOk).toBe(true)
    expect(Array.from(data)).toEqual(Array.from(WRAPPED_BYTES))
  })

  it('reads a real public key block with no armor headers', () => {
    const { data, crcOk } = dearmor(KEY_BLOCK)

    expect(crcOk).toBe(true)
    expect(data).toHaveLength(239)
    // 0x98: an old-format packet header, tag 6, one-byte length — the primary
    // public key, which is what the fingerprint is taken over.
    expect(data[0]).toBe(0x98)
    expect(sha256(data)).toBe(KEY_SHA256)
  })

  it('ignores prose before the header and after the footer', () => {
    const pasted = `Here's my key, let me know if it doesn't match:

${KEY_BLOCK}

-- sent from a train`

    expect(sha256(dearmor(pasted).data)).toBe(KEY_SHA256)
  })

  it('reads a block that came back through a mail client', () => {
    // CRLF endings and trailing spaces are what a paste out of a mail client
    // or a chat window looks like; the bytes are unchanged, so the checksum
    // must still match.
    const rewrapped = KEY_BLOCK.split('\n')
      .map((line) => `${line}  `)
      .join('\r\n')

    expect(dearmor(rewrapped).crcOk).toBe(true)
    expect(sha256(dearmor(rewrapped).data)).toBe(KEY_SHA256)
  })
})

describe('dearmor rejections', () => {
  /** Asserts the contract every failure shares: empty bytes, `crcOk: false`,
   * and no throw on the way there. */
  const expectRejected = (text: string): void => {
    const result = dearmor(text)

    expect(result.crcOk).toBe(false)
    expect(result.data).toHaveLength(0)
  }

  it('rejects a checksum line that is one bit different', () => {
    // 'X' (010111) to 'W' (010110): the smallest possible corruption of the
    // checksum, and the case the CRC exists to catch.
    const flipped = KEY_BLOCK.replace('=Xb+r', '=Wb+r')
    expect(flipped).not.toBe(KEY_BLOCK)

    expectRejected(flipped)
  })

  it('rejects a body line that is one character short', () => {
    // 320 body characters become 319, which is 3 modulo 4: base64 that
    // cannot be whole, so nothing is decoded and nothing is checksummed.
    expectRejected(
      KEY_BLOCK.replace(
        'mDMEaqI/oxYJKwYBBAHaRw8BAQdAmWkN2iNZ2aD4VmRFfOpP/5SJJzpAhFrpvIPG',
        'mDMEaqI/oxYJKwYBBAHaRw8BAQdAmWkN2iNZ2aD4VmRFfOpP/5SJJzpAhFrpvIP',
      ),
    )
  })

  it('rejects a body line with a character swapped for another', () => {
    // Same length, still base64, so only the checksum can tell.
    expectRejected(KEY_BLOCK.replace('ByakGti0', 'ByakGti1'))
  })

  it('rejects a block with no header line', () => {
    expectRejected(
      KEY_BLOCK.replace('-----BEGIN PGP PUBLIC KEY BLOCK-----\n', ''),
    )
  })

  it('rejects a block with no footer line', () => {
    expectRejected(
      KEY_BLOCK.replace('\n-----END PGP PUBLIC KEY BLOCK-----', ''),
    )
  })

  it('rejects a footer whose label is not the header label', () => {
    expectRejected(
      KEY_BLOCK.replace(
        '-----END PGP PUBLIC KEY BLOCK-----',
        '-----END PGP SIGNATURE-----',
      ),
    )
  })

  it('rejects a block with no checksum line', () => {
    // `crcOk: true` has to mean the checksum was there and matched, so armor
    // with nothing to check is a failure rather than an unchecked pass.
    expectRejected(KEY_BLOCK.replace('=Xb+r\n', ''))
  })

  it('rejects a line between the checksum and the footer', () => {
    expectRejected(KEY_BLOCK.replace('=Xb+r\n', '=Xb+r\nYWJj\n'))
  })

  it('rejects a body line that is not base64 at all', () => {
    expectRejected(KEY_BLOCK.replace('ByakGti0', '(redacted)'))
  })

  it('rejects the empty string', () => {
    expectRejected('')
  })

  it('does not throw on anything else a paste might be', () => {
    const junk = [
      '   ',
      '\n\n\n',
      '-----BEGIN PGP PUBLIC KEY BLOCK-----',
      '-----BEGIN PGP PUBLIC KEY BLOCK-----\n\n=Xb+r\n',
      '-----END PGP PUBLIC KEY BLOCK-----',
      'ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAIA',
      '-----BEGIN CERTIFICATE-----\nMIIB\n-----END CERTIFICATE-----',
      `${KEY_BLOCK}${KEY_BLOCK}`,
      KEY_BLOCK.replaceAll('\n', ' '),
      KEY_BLOCK.slice(0, KEY_BLOCK.length / 2),
      '=Xb+r',
      '\u0000\uffff',
    ]

    for (const text of junk) {
      const result = dearmor(text)
      expect(result.crcOk).toBe(false)
      expect(result.data).toHaveLength(0)
    }
  })
})
